// Test helper injected before the app's own scripts: find things by visible text or label and click them the
// way a pointer would (Radix menus open on pointerdown, not on click).
window.__pk = {
  find(label, sel = 'button,[role=menuitem],[role=tab],a,label') {
    const norm = (s) => (s || '').replace(/\s+/g, ' ').trim();
    const els = [...document.querySelectorAll(sel)].filter((e) => e.offsetParent !== null || e.getClientRects().length);
    return els.find((e) => norm(e.getAttribute('aria-label')) === label || norm(e.innerText) === label)
      || els.find((e) => norm(e.getAttribute('aria-label')).startsWith(label) || norm(e.title).startsWith(label) || norm(e.innerText).startsWith(label));
  },
  press(el, button = 0) {
    const r = el.getBoundingClientRect(), o = { bubbles: true, cancelable: true, clientX: r.x + r.width / 2, clientY: r.y + r.height / 2, button, pointerId: 1, pointerType: 'mouse', isPrimary: true };
    el.dispatchEvent(new PointerEvent('pointerdown', o)); el.dispatchEvent(new MouseEvent('mousedown', o));
    el.dispatchEvent(new PointerEvent('pointerup', o)); el.dispatchEvent(new MouseEvent('mouseup', o));
    if (button === 2) el.dispatchEvent(new MouseEvent('contextmenu', o)); else el.dispatchEvent(new MouseEvent('click', o));
  },
  // A missing control is an error, so a broken step can never pass as "same on both sides".
  click(label, sel) { const el = this.find(label, sel); if (!el) throw new Error('not on the page: ' + label); this.press(el); return 'clicked ' + label; },
  type(el, value) { // set an input the way React notices
    const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
    set.call(el, value); el.dispatchEvent(new Event('input', { bubbles: true })); return el.value;
  },
  menu() { return [...document.querySelectorAll('[role=menuitem],[role=menuitemradio],[role=option]')].map((e) => e.innerText.replace(/\s+/g, ' ').trim()).join(' | '); },
};
const __sleep = (ms) => new Promise((r) => setTimeout(r, ms));
// Close the welcome dialog, open one export dialog and type a messy file name into it.
window.__pk.exportDialog = async function (item) {
  this.click('Start Creating'); await __sleep(600);
  this.click('Export'); await __sleep(600);
  const hit = this.click(item, '[role=menuitem]'); await __sleep(1200);
  const input = [...document.querySelectorAll('[role=dialog] input')].find((i) => i.type === 'text' || !i.getAttribute('type'));
  if (!input) throw new Error(hit + ', but the dialog has no file name field');
  return 'file name becomes: ' + this.type(input, 'My Demo File!! __v2--');
};
window.__pk.rightClick = async function (text) {
  this.click('Start Creating'); await __sleep(600);
  const el = [...document.querySelectorAll('span,div')].find((e) => e.children.length === 0 && (e.innerText || '').trim() === text);
  if (!el) throw new Error('not on the page: ' + text);
  this.press(el, 2); await __sleep(700);
  return this.menu() || [...document.querySelectorAll('button')].slice(-14).map((b) => b.innerText.trim()).filter(Boolean).join(' | ');
};
window.__pk.tool = async function (label) {
  this.click('Start Creating'); await __sleep(500);
  return this.click(label);
};
